//! Source-scoped person-belief attribution. This path never consumes or relabels soft_truth.
//! Source passages and numeric assessments are supplied by the investigator, not fetched or
//! generated by this application. Only reference admission and attribution validation are automatic.

mod dates;
mod history;
mod investigation;
mod view;
pub use history::HistoricalComparison;
pub use investigation::{
    InvestigationReport, PropositionComparison, RelationshipReport, RelationshipSnapshot,
};
pub use view::{CurrentStance, LastDocumentedStance};

use dates::PartialDate;

use std::collections::{BTreeMap, BTreeSet};
use std::error::Error;

use belief_core::attribution::{
    AttributionKind, Conviction, ConvictionBasis, ObservationConfidence, PersonConfidence, Stance,
};
use belief_core::{EntityId, EvidenceId, EvidencePurpose, InferenceClass};
use belief_policy::PolicyConfig;
use belief_store::InMemoryBeliefStore;
use evidence_interchange::ValidatedEvidenceBatch;
use serde::{Deserialize, Serialize};

pub const ATTRIBUTION_SCHEMA: &str = "belief_person_attributions";
pub const ATTRIBUTION_VERSION: u32 = 1;

pub struct ComparisonInput<'a> {
    pub evidence_json: &'a str,
    pub attributions_json: &'a str,
    pub policy: BTreeMap<String, String>,
}

#[derive(Debug, Deserialize, Clone, PartialEq)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct AttributionDocument {
    schema: String,
    schema_version: u32,
    proposition: ScopedProposition,
    people: Vec<PersonInput>,
    observations: Vec<ObservationInput>,
    #[serde(default)]
    assessments: Vec<PersonAssessment>,
}

#[derive(Debug, Deserialize, Serialize, Clone, PartialEq)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ScopedProposition {
    pub id: String,
    pub text: String,
    pub scope: String,
}

#[derive(Debug, Deserialize, Clone, PartialEq)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct PersonInput {
    id: String,
    display_name: String,
    /// Source-local subject token, never a cross-repository identity.
    subject_id: String,
    source_repository: String,
    scope_id: String,
}

#[derive(Debug, Deserialize, Serialize, Clone, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Span {
    pub start: usize,
    pub end: usize,
}

#[derive(Debug, Deserialize, Serialize, Clone, PartialEq)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct AssessedScore {
    pub value: f64,
    /// Analyst or scripted_example; never an implicit model-confidence conversion.
    pub assessed_by: String,
}

impl AssessedScore {
    fn validate(&self) -> Result<(), Box<dyn Error>> {
        if !matches!(self.assessed_by.as_str(), "analyst" | "scripted_example") {
            return Err(invalid(
                "assessedBy must be analyst or scripted_example; model scores require their own reviewed provenance",
            ));
        }
        Ok(())
    }
}

#[derive(Debug, Deserialize, Clone, PartialEq)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct ObservationInput {
    id: String,
    /// Required in version-3 investigations; absent in single-proposition documents.
    #[serde(default)]
    proposition_id: Option<String>,
    person_id: String,
    evidence_id: String,
    kind: String,
    stance: String,
    /// Exact passage supplied by the investigator, tied to one producer evidence reference.
    passage: String,
    span: Span,
    #[serde(default)]
    confidence_observation: Option<AssessedScore>,
    #[serde(default)]
    conviction: Option<ConvictionInput>,
    /// When the person expressed this, as precisely as the source states it.
    #[serde(default)]
    expressed_at: Option<String>,
    /// When the source published the expression, if different and known.
    #[serde(default)]
    published_at: Option<String>,
    /// When the investigation found or ingested the source.
    #[serde(default)]
    discovered_at: Option<String>,
}

#[derive(Debug, Deserialize, Clone, PartialEq)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct ConvictionInput {
    value: f64,
    basis: String,
    assessed_by: String,
}

#[derive(Debug, Deserialize, Clone, PartialEq)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct PersonAssessment {
    /// Required in version-3 investigations; absent in single-proposition documents.
    #[serde(default)]
    proposition_id: Option<String>,
    person_id: String,
    stance: String,
    #[serde(default)]
    confidence_person: Option<AssessedScore>,
    #[serde(default)]
    observation_ids: Vec<String>,
    #[serde(default)]
    reviewed_conflicts: bool,
    /// `documented` (default): the stance the cited observations document. `current`: a tentative,
    /// reviewable estimate of the present stance (Decisions 1.4.25 and 1.4.27).
    #[serde(default)]
    time_scope: Option<String>,
    /// Required for a current-stance estimate: why the cited evidence supports it and its limits.
    #[serde(default)]
    rationale: Option<String>,
    /// The date a current-stance estimate refers to.
    #[serde(default)]
    as_of: Option<String>,
}

#[derive(Debug, Serialize)]
pub struct ComparisonReport {
    pub report: &'static str,
    pub report_version: u32,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub revision: Option<usize>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub revision_reason: Option<String>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub history: Vec<HistoricalComparison>,
    #[serde(skip_serializing_if = "BTreeMap::is_empty")]
    pub supersedes: BTreeMap<String, String>,
    pub proposition: ScopedProposition,
    pub policy_profile: String,
    pub evidence_exporter: String,
    pub evidence_batch_revision: String,
    /// These are observed/assessed positions, not findings about objective truth.
    pub people: Vec<PersonReport>,
}

#[derive(Debug, Serialize)]
pub struct PersonReport {
    pub id: String,
    pub display_name: String,
    pub scope_id: String,
    pub source_repository: String,
    pub subject_id: String,
    /// One of `assessed`, `unassessed`, `conflicted`, `differs_over_time`, `no_stance_evidence`.
    pub assessment_status: &'static str,
    /// The reviewed documented stance, when `assessment_status` is `assessed`.
    pub stance: Option<String>,
    pub confidence_person: Option<AssessedScore>,
    pub supporting_observation_ids: Vec<String>,
    pub has_conflicting_positions: bool,
    /// Observations on both sides of an endorses / endorses-negation opposition.
    pub conflicting_observation_ids: Vec<String>,
    pub last_documented: Option<LastDocumentedStance>,
    pub current_stance: CurrentStance,
    pub observations: Vec<ObservationReport>,
}

#[derive(Debug, Serialize)]
pub struct ObservationReport {
    pub id: String,
    pub kind: String,
    pub stance: String,
    pub passage: String,
    pub span: Span,
    pub confidence_observation: Option<AssessedScore>,
    pub conviction: Option<ConvictionReport>,
    pub expressed_at: Option<String>,
    pub published_at: Option<String>,
    pub discovered_at: Option<String>,
    pub evidence: ReferencedEvidence,
}

#[derive(Debug, Serialize)]
pub struct ConvictionReport {
    pub value: f64,
    pub basis: String,
    pub assessed_by: String,
}

#[derive(Debug, Serialize)]
pub struct ReferencedEvidence {
    pub id: String,
    pub family_id: String,
    pub class: String,
    pub source_repository: String,
    pub source_scope_id: String,
    pub source_record_id: String,
    pub source_revision: String,
    pub producer_name: String,
    pub producer_revision: String,
    pub producer_model: Option<String>,
    pub producer_config_hash: Option<String>,
    pub policy_profile: String,
    pub authorized_purpose: &'static str,
}

struct ObservationMarker {
    person_id: String,
    stance: Stance,
    has_confidence: bool,
    expressed_at: Option<PartialDate>,
}

fn invalid(message: impl Into<String>) -> Box<dyn Error> {
    message.into().into()
}
fn required(name: &str, value: &str) -> Result<(), Box<dyn Error>> {
    if value.trim().is_empty() {
        return Err(invalid(format!("{name} must not be empty")));
    }
    Ok(())
}

fn parsed_stance(value: &str) -> Result<Stance, Box<dyn Error>> {
    Stance::parse(value).ok_or_else(|| invalid(format!("unsupported stance {value}")))
}

pub fn compare(input: &ComparisonInput<'_>) -> Result<AttributionReport, Box<dyn Error>> {
    let policy = attribution_policy(&input.policy)?;
    let batch = ValidatedEvidenceBatch::parse_json(input.evidence_json)?;
    let mut store = InMemoryBeliefStore::default();
    let evidence_exporter = batch.exporter_name().to_owned();
    let evidence_batch_revision = batch.revision().to_owned();
    store.insert_authorized_evidence_batch(batch.authorize(&policy)?)?;
    compare_annotations(
        serde_json::from_str(input.attributions_json)?,
        &policy,
        &store,
        &evidence_exporter,
        &evidence_batch_revision,
    )
}

/// The policy for descriptive person attribution, refusing unknown keys.
pub(crate) fn attribution_policy(
    pairs: &BTreeMap<String, String>,
) -> Result<PolicyConfig, Box<dyn Error>> {
    if let Some(key) = pairs
        .keys()
        .find(|key| !belief_policy::POLICY_KEYS.contains(&key.as_str()))
    {
        return Err(invalid(format!("unknown policy key {key}")));
    }
    let policy = PolicyConfig::from_pairs(pairs.clone())?;
    policy
        .inference_decision(InferenceClass::Descriptive)
        .map_err(|reason| invalid(format!("descriptive attribution denied: {reason}")))?;
    Ok(policy)
}

/// Compares annotations of any supported version against already authorized evidence.
pub(crate) fn compare_annotations(
    document: serde_json::Value,
    policy: &PolicyConfig,
    store: &InMemoryBeliefStore,
    evidence_exporter: &str,
    evidence_batch_revision: &str,
) -> Result<AttributionReport, Box<dyn Error>> {
    match document
        .get("schemaVersion")
        .and_then(serde_json::Value::as_u64)
    {
        Some(1) => compare_document(
            serde_json::from_value(document)?,
            policy,
            store,
            evidence_exporter,
            evidence_batch_revision,
            &BTreeSet::new(),
        )
        .map(AttributionReport::Comparison),
        Some(2) => history::compare_history(
            serde_json::from_value(document)?,
            policy,
            store,
            evidence_exporter,
            evidence_batch_revision,
            1,
        )
        .map(AttributionReport::Comparison),
        Some(3) => investigation::compare_investigation(
            serde_json::from_value(document)?,
            policy,
            store,
            evidence_exporter,
            evidence_batch_revision,
        )
        .map(AttributionReport::Investigation),
        _ => Err(invalid("unsupported person-attribution schema/version")),
    }
}

/// A single-proposition comparison (versions 1 and 2) or a multi-proposition investigation (3).
#[derive(Debug, Serialize)]
#[serde(untagged)]
pub enum AttributionReport {
    Comparison(ComparisonReport),
    Investigation(InvestigationReport),
}

/// Validates one annotation snapshot. Assessments of `stale` people are validated but not applied,
/// because later evidence changed after they were reviewed.
fn compare_document(
    document: AttributionDocument,
    policy: &PolicyConfig,
    store: &InMemoryBeliefStore,
    evidence_exporter: &str,
    evidence_batch_revision: &str,
    stale: &BTreeSet<String>,
) -> Result<ComparisonReport, Box<dyn Error>> {
    if document.schema != ATTRIBUTION_SCHEMA || document.schema_version != ATTRIBUTION_VERSION {
        return Err(invalid("unsupported person-attribution schema/version"));
    }
    for (name, value) in [
        ("proposition.id", document.proposition.id.as_str()),
        ("proposition.text", document.proposition.text.as_str()),
        ("proposition.scope", document.proposition.scope.as_str()),
    ] {
        required(name, value)?;
    }
    if document
        .observations
        .iter()
        .filter_map(|observation| observation.proposition_id.as_deref())
        .chain(
            document
                .assessments
                .iter()
                .filter_map(|assessment| assessment.proposition_id.as_deref()),
        )
        .any(|id| id != document.proposition.id)
    {
        return Err(invalid(
            "an observation or assessment refers to a different proposition",
        ));
    }
    let mut people = BTreeMap::<String, PersonInput>::new();
    let mut source_people = BTreeSet::new();
    for person in document.people {
        required("person.id", &person.id)?;
        required("person.displayName", &person.display_name)?;
        required("person.scopeId", &person.scope_id)?;
        required("person.sourceRepository", &person.source_repository)?;
        required("person.subjectId", &person.subject_id)?;
        EntityId::new(person.id.clone())?;
        EntityId::new(person.subject_id.clone())?;
        if !source_people.insert((
            person.source_repository.clone(),
            person.scope_id.clone(),
            person.subject_id.clone(),
        )) {
            return Err(invalid("duplicate source-local person"));
        }
        if people.insert(person.id.clone(), person).is_some() {
            return Err(invalid("duplicate person id"));
        }
    }

    let mut by_person = BTreeMap::<String, Vec<ObservationReport>>::new();
    let mut markers = BTreeMap::<String, ObservationMarker>::new();
    for observation in document.observations {
        required("observation.id", &observation.id)?;
        if markers.contains_key(&observation.id) {
            return Err(invalid(format!("duplicate observation {}", observation.id)));
        }
        let person = people
            .get(&observation.person_id)
            .ok_or_else(|| invalid(format!("unknown person {}", observation.person_id)))?;
        let evidence_id = EvidenceId::new(observation.evidence_id.clone())?;
        let stored = store
            .evidence(&evidence_id)
            .ok_or_else(|| invalid(format!("unknown imported evidence {evidence_id}")))?;
        if !stored.validity.is_active() {
            return Err(invalid(format!("withdrawn evidence {evidence_id}")));
        }
        let evidence = &stored.value;
        policy
            .evidence_decision(evidence, EvidencePurpose::DirectSupport)
            .map_err(|reason| {
                invalid(format!(
                    "evidence {evidence_id} not authorized for direct support: {reason}"
                ))
            })?;
        if evidence.subject.as_ref().map(EntityId::as_str) != Some(person.subject_id.as_str())
            || evidence.provenance.source.repository() != person.source_repository
            || evidence.provenance.source.scope_id() != person.scope_id
        {
            return Err(invalid(format!(
                "evidence {evidence_id} is not bound to source-local person {} in repository {} / scope {}",
                person.subject_id, person.source_repository, person.scope_id
            )));
        }
        if observation.passage.trim().is_empty()
            || observation.passage.len() > 4096
            || observation.span.start >= observation.span.end
        {
            return Err(invalid(format!(
                "observation {} needs a nonempty bounded passage and valid source offsets",
                observation.id
            )));
        }

        let kind = AttributionKind::parse(&observation.kind)
            .ok_or_else(|| invalid(format!("unsupported attribution kind {}", observation.kind)))?;
        let stance = parsed_stance(&observation.stance)?;
        if kind == AttributionKind::QuotationOrCriticism
            && (stance != Stance::NoStance
                || observation.confidence_observation.is_some()
                || observation.conviction.is_some())
        {
            return Err(invalid(
                "quotation/criticism is not evidence of endorsement by itself",
            ));
        }
        if stance == Stance::NoStance
            && (observation.confidence_observation.is_some() || observation.conviction.is_some())
        {
            return Err(invalid(
                "an observation without a stance must leave both scores unknown",
            ));
        }
        if stance == Stance::SuspendsJudgment
            && (!matches!(
                kind,
                AttributionKind::ExplicitEndorsement | AttributionKind::ReportedPosition
            ) || observation.conviction.is_some())
        {
            return Err(invalid(
                "suspending judgment must be expressed (explicit or reported), not inferred, and has no conviction about P",
            ));
        }
        let mut dates = [None, None, None];
        for (slot, (field, value)) in dates.iter_mut().zip([
            ("expressedAt", &observation.expressed_at),
            ("publishedAt", &observation.published_at),
            ("discoveredAt", &observation.discovered_at),
        ]) {
            if let Some(value) = value {
                *slot = Some(PartialDate::parse(field, value)?);
            }
        }
        if let [Some(expressed), Some(published), _] = dates {
            if published.certainly_before(expressed) {
                return Err(invalid(format!(
                    "observation {} is published before it was expressed",
                    observation.id
                )));
            }
        }
        if let Some(score) = &observation.confidence_observation {
            ObservationConfidence::new(score.value)?;
            score.validate()?;
        }
        let conviction = if let Some(value) = observation.conviction {
            Conviction::new(value.value)?;
            let basis = ConvictionBasis::parse(&value.basis)
                .ok_or_else(|| invalid("conviction basis must be self_reported or inferred"))?;
            AssessedScore {
                value: value.value,
                assessed_by: value.assessed_by.clone(),
            }
            .validate()?;
            if observation.confidence_observation.is_none()
                || (basis == ConvictionBasis::SelfReported
                    && kind != AttributionKind::ExplicitEndorsement)
            {
                return Err(invalid(
                    "conviction needs a scored attribution; self-reported certainty needs an explicit first-person stance",
                ));
            }
            Some(ConvictionReport {
                value: value.value,
                basis: basis.as_str().to_owned(),
                assessed_by: value.assessed_by,
            })
        } else {
            None
        };

        markers.insert(
            observation.id.clone(),
            ObservationMarker {
                person_id: observation.person_id.clone(),
                stance,
                has_confidence: observation.confidence_observation.is_some(),
                expressed_at: dates[0],
            },
        );
        by_person
            .entry(person.id.clone())
            .or_default()
            .push(ObservationReport {
                id: observation.id,
                kind: kind.as_str().to_owned(),
                stance: stance.as_str().to_owned(),
                passage: observation.passage,
                span: observation.span,
                confidence_observation: observation.confidence_observation,
                conviction,
                expressed_at: observation.expressed_at,
                published_at: observation.published_at,
                discovered_at: observation.discovered_at,
                evidence: ReferencedEvidence {
                    id: evidence.id.to_string(),
                    family_id: evidence.family.to_string(),
                    class: evidence.class.as_str().to_owned(),
                    source_repository: evidence.provenance.source.repository().to_owned(),
                    source_scope_id: evidence.provenance.source.scope_id().to_owned(),
                    source_record_id: evidence.provenance.source.record_id().to_owned(),
                    source_revision: evidence.provenance.source.revision().to_owned(),
                    producer_name: evidence.provenance.producer.name().to_owned(),
                    producer_revision: evidence.provenance.producer.revision().to_owned(),
                    producer_model: evidence.provenance.producer.model().map(str::to_owned),
                    producer_config_hash: evidence
                        .provenance
                        .producer
                        .config_hash()
                        .map(str::to_owned),
                    policy_profile: policy.profile().as_str().to_owned(),
                    authorized_purpose: EvidencePurpose::DirectSupport.as_str(),
                },
            });
    }

    let mut documented = BTreeMap::<String, view::Assessment>::new();
    let mut current = BTreeMap::<String, view::Assessment>::new();
    for assessment in document.assessments {
        if !people.contains_key(&assessment.person_id) {
            return Err(invalid(format!(
                "unknown assessment person {}",
                assessment.person_id
            )));
        }
        let is_current = match assessment.time_scope.as_deref() {
            None | Some("documented") => false,
            Some("current") => true,
            Some(other) => {
                return Err(invalid(format!("unsupported assessment timeScope {other}")))
            }
        };
        let target = if is_current {
            &mut current
        } else {
            &mut documented
        };
        if target.contains_key(&assessment.person_id) {
            return Err(invalid(format!(
                "duplicate {} person assessment {}",
                if is_current { "current" } else { "documented" },
                assessment.person_id
            )));
        }
        let stance = parsed_stance(&assessment.stance)?;
        if let Some(score) = &assessment.confidence_person {
            PersonConfidence::new(score.value)?;
            score.validate()?;
            if !stance.is_attributed() {
                return Err(invalid(
                    "a numerical person confidence needs a definite reviewed stance",
                ));
            }
        }
        let unique = assessment.observation_ids.iter().collect::<BTreeSet<_>>();
        if unique.len() != assessment.observation_ids.len() {
            return Err(invalid("duplicate supporting observation id"));
        }
        for id in &assessment.observation_ids {
            let observed = markers
                .get(id)
                .ok_or_else(|| invalid(format!("unknown assessment observation {id}")))?;
            if observed.person_id != assessment.person_id {
                return Err(invalid(format!(
                    "observation {id} belongs to another person"
                )));
            }
        }
        if is_current {
            if assessment
                .rationale
                .as_deref()
                .is_none_or(|text| text.trim().is_empty())
            {
                return Err(invalid(
                    "a current-stance estimate needs a rationale explaining its evidence and limits",
                ));
            }
            if let Some(as_of) = &assessment.as_of {
                PartialDate::parse("asOf", as_of)?;
            }
            if !stance.is_attributed() || assessment.observation_ids.is_empty() {
                return Err(invalid(
                    "a current-stance estimate needs a definite stance and cited observations; omit it when the present stance is unknown",
                ));
            }
        } else {
            if assessment.rationale.is_some() || assessment.as_of.is_some() {
                return Err(invalid(
                    "rationale and asOf belong to a current-stance estimate",
                ));
            }
            if stance.is_attributed() && assessment.confidence_person.is_none() {
                return Err(invalid(
                    "a definite person stance requires a reviewed confidencePerson score",
                ));
            }
            for id in &assessment.observation_ids {
                let observed = &markers[id];
                if assessment.confidence_person.is_some()
                    && (observed.stance != stance || !observed.has_confidence)
                {
                    return Err(invalid(format!(
                        "supporting observation {id} must have a score for the assessed stance"
                    )));
                }
            }
            if assessment.confidence_person.is_some()
                && !assessment.observation_ids.iter().any(|id| {
                    markers
                        .get(id)
                        .is_some_and(|item| item.stance == stance && item.has_confidence)
                })
            {
                return Err(invalid(
                    "a person confidence needs a cited observation scored for the same stance",
                ));
            }
        }
        // A legacy "undetermined" documented assessment records no stance; keep it out of the view.
        if stance.is_attributed() {
            target.insert(
                assessment.person_id.clone(),
                view::Assessment {
                    stance,
                    confidence_person: assessment.confidence_person,
                    observation_ids: assessment.observation_ids,
                    reviewed_conflicts: assessment.reviewed_conflicts,
                    rationale: assessment.rationale,
                    as_of: assessment.as_of,
                },
            );
        }
    }

    let mut results = Vec::new();
    for (id, person) in people {
        let mut observations = by_person.remove(&id).unwrap_or_default();
        observations.sort_by(|a, b| a.id.cmp(&b.id));
        let (documented, current) = if stale.contains(&id) {
            (None, None)
        } else {
            (documented.remove(&id), current.remove(&id))
        };
        let derived = view::derive(&id, &observations, &markers, documented, current)?;
        results.push(PersonReport {
            id,
            display_name: person.display_name,
            scope_id: person.scope_id,
            source_repository: person.source_repository,
            subject_id: person.subject_id,
            assessment_status: derived.status,
            stance: derived.stance,
            confidence_person: derived.confidence_person,
            supporting_observation_ids: derived.supporting_observation_ids,
            has_conflicting_positions: !derived.conflicting_observation_ids.is_empty(),
            conflicting_observation_ids: derived.conflicting_observation_ids,
            last_documented: derived.last_documented,
            current_stance: derived.current_stance,
            observations,
        });
    }

    Ok(ComparisonReport {
        report: "person_belief_comparison",
        report_version: 1,
        revision: None,
        revision_reason: None,
        history: Vec::new(),
        supersedes: BTreeMap::new(),
        proposition: document.proposition,
        policy_profile: policy.profile().as_str().to_owned(),
        evidence_exporter: evidence_exporter.to_owned(),
        evidence_batch_revision: evidence_batch_revision.to_owned(),
        people: results,
    })
}
